requestAnimationFrame(draw)}
function showToast(text){let el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),1500)}
function hud(){document.querySelector('#damage').innerHTML=Math.floor(damage)+'<em>%</em>';document.querySelector('#score').textContent=String(score).padStart(4,'0');document.querySelector('#energyText').textContent=Math.floor(energy)+'%';document.querySelector('#energyBar').style.width=energy+'%'}
function say(html){document.querySelector('#log').innerHTML=html;}
function pick(px,py){let nearest=null,best=Infinity;for(const b of buildings){if(b.hp<=0)continue;let p=project(b.x,b.y),dx=(px-p[0])/geometry.sx,dy=(py-(p[1]-b.h*b.hp*.45))/geometry.sy,d=dx*dx+dy*dy;if(d<best){best=d;nearest=b}}return best<9?nearest:null}
function impact(b){let now=performance.now(),w=weapons[selected];if(energy<w.cost){showToast('ENERGIA INSUFFICIENTE · SI RICARICA');say('<span class="accent">✧</span> &nbsp;Il potere si sta rigenerando.');return}energy-=w.cost;if(now-lastHit<6500)combo=Math.min(combo+1,9);else combo=1;lastHit=now;document.querySelector('#combo').textContent='COMBO ×'+combo;
let radius=w.r,damaged=0;for(const target of buildings){let dist=Math.hypot((target.x-b.x)*.91,(target.y-b.y)*1.06);if(dist>radius||target.hp<=0)continue;let fall=Math.max(.12,1-dist/(radius*1.25));let hit=(selected==='storm'?.43:selected==='vortex'?.57:selected==='nova'?.72:.69)*fall*(.88+rand()*.28);let before=target.hp;target.hp=Math.max(0,target.hp-hit);damaged+=before-target.hp;if(before>0&&target.hp===0){let p=project(target.x,target.y-target.h*.28);for(let n=0;n<5;n++)particles.push({x:p[0],y:p[1],vx:(rand()-.5)*2.8,vy:-.3-rand()*1.7,size:2+rand()*4,color:['#ffc26b','#ff7859','#85c8d2'][n%3],start:now,life:500+rand()*600})}}
let p=project(b.x,b.y);effects.push({x:b.x,y:b.y,start:now,life:selected==='storm'?900:1150,radius,type:selected,color:w.color,index:Math.floor(rand()*buildings.length)});if(selected==='storm'){for(let i=0;i<5;i++){let target=buildings[Math.floor(rand()*buildings.length)];if(target)effects.push({x:target.x,y:target.y,start:now+i*50,life:650,radius:.35,type:'storm',color:w.color,index:Math.floor(rand()*buildings.length)})}}
let points=Math.round(damaged*185*combo);score+=points;damage=Math.min(100,(1-buildings.reduce((a,v)=>a+v.hp,0)/total)*100);hud();document.querySelector('#hint').style.opacity=0;const phrases={meteor:'Una stella cade dal cielo.',storm:'Il cielo si piega al tuo volere.',vortex:'La gravità reclama il suo tributo.',nova:'La luce divina avvolge la città.'};say(`<span class="accent">✦ ${weapons[selected].name.toUpperCase()}</span> &nbsp;${phrases[selected]}<br><span style="color:#7f8ba5">IMPATTO ${Math.round(damaged*100)}% · +${points} POTERE</span>`);if(damage>=99.9){say('<span class="accent">✦ TRIONFO COSMICO</span> &nbsp;Nova Aurelia è stata ridotta a rovine.<br>Il mondo attende una nuova creazione.')}if(soundOn)playTone(selected);}
function playTone(type){try{audio??=new AudioContext();let osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.type=type==='storm'?'square':'sine';osc.frequency.setValueAtTime(type==='nova'?95:type==='storm'?480:145,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(38,audio.currentTime+.4);gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.42);osc.start();osc.stop(audio.currentTime+.43)}catch{}}
function position(e){let r=canvas.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]}
canvas.addEventListener('pointermove',e=>{let [x,y]=position(e);pointer=pick(x,y);let c=document.querySelector('#coords');if(pointer){c.textContent=`SETTORE ${String(pointer.x+1).padStart(2,'0')} · ${String(pointer.y+1).padStart(2,'0')}`;canvas.style.cursor='crosshair'}else{c.textContent='N 40°43′  ·  E 73°59′'}});
canvas.addEventListener('pointerleave',()=>{pointer=null});canvas.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();let [x,y]=position(e),b=pick(x,y);if(b)impact(b);else showToast('SCEGLI UN EDIFICIO COME BERSAGLIO')});
document.querySelectorAll('.weapon').forEach((button,i)=>button.addEventListener('click',()=>{selected=button.dataset.weapon;document.querySelectorAll('.weapon').forEach(b=>b.classList.toggle('active',b===button));document.querySelector('#hint').innerHTML=`POTERE SELEZIONATO: <b>${weapons[selected].name.toUpperCase()}</b> · TOCCA LA CITTÀ`;document.querySelector('#hint').style.opacity=1}));
document.querySelector('#reset').addEventListener('click',()=>{for(const b of buildings)b.hp=1;energy=100;score=damage=0;combo=1;lastHit=0;effects=[];particles=[];hud();document.querySelector('#combo').textContent='COMBO ×1';say('<span class="accent">✦</span> &nbsp;Nova Aurelia è stata ricostruita.<br>Il cielo è nelle tue mani, divinità.');document.querySelector('#hint').style.opacity=1;showToast('CITTÀ RINNOVATA')});
document.querySelector('#howto').addEventListener('click',()=>showToast('SCEGLI UN POTERE · CLICCA UN EDIFICIO · DISTRUGGI!'));
document.querySelector('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';showToast(soundOn?'SUONI ATTIVI':'SUONI DISATTIVATI');if(soundOn)playTone('storm')});
window.addEventListener('keydown',e=>{if('1234'.includes(e.key)){document.querySelectorAll('.weapon')[Number(e.key)-1].click()}if(e.key.toLowerCase()==='r'&&!e.repeat)document.querySelector('#reset').click()});
setInterval(()=>{let now=performance.now();energy=Math.min(100,energy+(now-lastTick)*.0027);lastTick=now;hud();effects=effects.filter(v=>now-v.start<v.life)},180);
new ResizeObserver(resize).observe(wrap);resize();hud();requestAnimationFrame(draw);
})();
</script></body></html>

